'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
 check:'M9 11l3 3L22 4 M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11',
 tasks:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',
 calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2z',
 users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',
 clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
 report:'M4 21V3h16v18z M8 16v-3 M12 16V8 M16 16v-5',
 flag:'M4 22V3 M4 3c5-4 11 4 16 0v11c-5 4-11-4-16 0',
 plus:'M12 5v14 M5 12h14', arrow:'M7 17L17 7 M7 7h10v10',
 refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-2l2 3 M4 16l2 3a7 7 0 0 0 12-2',
 logout:'M9 21H4V3h5 M14 8l5 4-5 4 M8 12h13', close:'M6 6l12 12 M6 18L18 6',
 leaf:'M20 3C7 2 1 9 6 16s18 1 14-13z M4 21L16 9', download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',
 search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0', lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4'
};
const icon = n => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n] || paths.tasks}"/></svg>`;
const roleNames = {admin:'Quản trị viên',manager:'Trưởng nhóm',content:'Nhân viên Content',intern:'Thực tập sinh'};
const statusNames = {pending:'Chờ bắt đầu',doing:'Đang thực hiện',review:'Chờ duyệt',revision:'Cần chỉnh sửa',done:'Đã nghiệm thu',cancelled:'Đã hủy'};
const priorities = {low:'Thấp',normal:'Vừa',high:'Cao',urgent:'Khẩn cấp'};
const pubNames = {unscheduled:'Chưa lên lịch',scheduled:'Đã lên lịch',published:'Đã đăng'};
const stageNames = {script:'Kịch bản',shoot:'Quay',edit:'Dựng'};
const stageStatus = {todo:'Chưa bắt đầu',doing:'Đang thực hiện',done:'Đã bàn giao'};
let data = {users:[],tasks:[],reports:[]}, csrf = '', route = 'overview', currentUser = null;
let filters = {search:'',owner:'',channel:'',status:'all'}, taskView = 'list', calendarOffset = 0;
let reportKind = 'daily', reportPeriod = '', reportOwner = '', reportSummary = null;
let previousFocus = null, toastTimer;
const manager = () => ['admin','manager'].includes(currentUser?.role);
const user = id => data.users.find(u => String(u.id) === String(id)) || {id,name:'Tài khoản đã ngừng hoạt động',role:'content'};
const own = t => t.ownerId === currentUser.id || t.stages.some(s => s.ownerId === currentUser.id);
const canPublish = t => manager() || t.ownerId === currentUser.id;
const canReview = t => currentUser.role === 'admin' || (manager() && t.reviewerId === currentUser.id);
const today = () => data.today || new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Bangkok'});
const dateAdd = (date,n) => {let d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const monday = d => {let dt = new Date(d+'T12:00:00Z');return dateAdd(d,-((dt.getUTCDay()+6)%7))};
const fmt = (d,year=false) => d ? new Date(String(d).slice(0,10)+'T12:00:00Z').toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit',...(year?{year:'numeric'}:{})}) : 'Chưa đặt';
const fmtTime = d => d ? new Date(d).toLocaleString('vi-VN',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'}) : '';
const active = t => !['done','cancelled'].includes(t.status);
const overdue = t => active(t) && t.due < today();
const progress = t => Math.round(t.stages.filter(s=>s.status==='done').length / Math.max(t.stages.length,1)*100);
const bar = n => `<div class="bar"><i style="width:${Math.min(n,100)}%"></i></div>`;
const badge = (s,n=statusNames) => `<span class="status s-${esc(s)}">${esc(n[s]||s)}</span>`;
function initials(name){return name.trim().split(/\s+/).slice(-2).map(n=>n[0]).join('').toUpperCase()}
function avatar(id){const u=user(id);return `<span class="avatar" aria-hidden="true">${esc(initials(u.name))}</span>`}
const person = id => `<span class="person">${avatar(id)}<span>${esc(user(id).name)}</span></span>`;
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
async function api(path,method='GET',body){
 const headers={}; if(body!==undefined)headers['Content-Type']='application/json';if(csrf)headers['X-CSRF-Token']=csrf;
 const response=await fetch('/api'+path,{method,headers,credentials:'same-origin',...(body!==undefined?{body:JSON.stringify(body)}:{})});
 let value;try{value=await response.json()}catch{throw new Error('Máy chủ chưa phản hồi đúng. Kiểm tra cửa sổ chạy server và thử tải lại.')}
 if(!response.ok){if(response.status===401 && path!=='/login' && path!=='/password'){currentUser=null;closeModal();authPage(false)}const error=new Error(value.error||'Không thể thực hiện thao tác.');error.status=response.status;throw error}
 return value;
}
async function refresh(){data=await api('/bootstrap');currentUser=data.user;csrf=data.csrfToken||csrf;render()}
async function runForm(form,fn){
 const old=form.querySelector('.form-error');if(old)old.remove();const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);
 try{await fn()}catch(e){const div=document.createElement('div');div.className='form-error';div.setAttribute('role','alert');div.textContent=e.message;form.prepend(div);if(e.status===409)toast('Dữ liệu đã thay đổi. Đóng chi tiết và bấm Làm mới để lấy bản mới.')}finally{buttons.forEach(b=>b.disabled=false)}
}
function brand(){return `<a class="brand" href="#" aria-label="Super Net"><b>S</b><span>supernet<span class="brand-dot">.</span><small>CONTENT WORKSPACE</small></span></a>`}
async function init(){try{const status=await api('/status');if(status.setupRequired){authPage(true);return}const session=await api('/session');currentUser=session.user;csrf=session.csrfToken;await refresh()}catch(e){if(e.status!==401){$('#root').innerHTML=`<div class="loading"><h2>Chưa kết nối được máy chủ</h2><p>${esc(e.message)}</p><button id="retry-init">Thử lại</button></div>`;$('#retry-init').onclick=()=>location.reload()}}}
function authPage(setup){
 $('#root').innerHTML=`<div class="auth-page"><section class="auth-story">${brand()}<h1>Công việc rõ ràng.<br>Đội ngũ vững vàng.</h1><p>Một không gian chung cho kế hoạch nội dung, tiến độ sản xuất và những bước tiến mỗi ngày.</p><div class="auth-steps"><span>01 · Lên kế hoạch</span><span>02 · Cùng thực hiện</span><span>03 · Ghi nhận kết quả</span></div></section><section class="auth-form"><div class="eyebrow">SUPER NET · CONTENT MARKETING</div><h2>${setup?'Tạo không gian của bạn':'Chào mừng trở lại'}</h2><p>${setup?'Thiết lập tài khoản quản trị đầu tiên. Sau đó bạn có thể tạo tài khoản và phân quyền cho từng thành viên.':'Đăng nhập để xem công việc và cập nhật tiến độ của bạn.'}</p><form id="auth-form">${setup?field('Họ và tên','<input name="name" required maxlength="100" autocomplete="name" placeholder="Tên người quản lý">'):''}${field('Tên đăng nhập','<input name="username" required autocomplete="username" minlength="3" maxlength="60" placeholder="Ví dụ: thanh.nguyen">')}${field('Mật khẩu',`<input name="password" required type="password" ${setup?'minlength="10"':''} autocomplete="${setup?'new-password':'current-password'}" placeholder="${setup?'Ít nhất 10 ký tự':'Nhập mật khẩu của bạn'}">`)}${setup?field('Nhập lại mật khẩu','<input name="confirm" type="password" required minlength="10" autocomplete="new-password">'):''}<button class="primary" type="submit">${icon(setup?'plus':'arrow')}${setup?'Tạo tài khoản quản trị':'Đăng nhập'}</button></form><p class="auth-foot">${setup?'Chỉ thiết lập lần đầu trên máy chạy server qua localhost:5001.':'Tài khoản do quản trị viên hoặc trưởng nhóm cấp. Quên mật khẩu? Liên hệ người quản lý.'}</p></section></div>`;
 $('#auth-form').onsubmit=e=>{e.preventDefault();runForm(e.target,async()=>{const v=Object.fromEntries(new FormData(e.target));if(setup&&v.password!==v.confirm)throw Error('Hai mật khẩu chưa khớp.');delete v.confirm;const r=await api(setup?'/setup':'/login','POST',v);csrf=r.csrfToken;currentUser=r.user;route='overview';await refresh()})};
}
function field(label,input,full=false,hint=''){return `<label class="field ${full?'full':''}">${label}${input}${hint?`<small>${hint}</small>`:''}</label>`}
function opts(entries,sel){return entries.map(([v,l])=>`<option value="${esc(v)}" ${String(sel)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}
function userOpts(sel,reviewers=false){return opts(data.users.filter(u=>(u.active||u.id===sel)&&(!reviewers||['admin','manager'].includes(u.role))).map(u=>[u.id,u.name+(u.active?'':' (đã khóa)')]),sel)}
const navs = () => [['overview','grid','Tổng quan'],['mine','check','Việc của tôi'],['tasks','tasks','Kế hoạch nội dung'],['calendar','calendar','Lịch nội dung'],...(manager()?[['reviews','clock','Chờ phê duyệt']]:[]),['reports','report','Báo cáo ngày / tuần'],...(manager()?[['team','users','Đội ngũ & tài khoản']]:[])];
function navigate(name){route=name;filters={search:'',owner:'',channel:'',status:'all'};reportSummary=null;render()}
function render(){
 if(!currentUser)return;
 const reviewCount=data.tasks.filter(t=>t.status==='review'&&canReview(t)).length;
 $('#root').innerHTML=`<aside>${brand()}<div class="workspace-label"><span>SN</span><span><strong>Super Net Workspace</strong><small>Content Marketing</small></span></div><div class="nav-label">KHÔNG GIAN LÀM VIỆC</div><nav>${navs().map(([id,ic,l])=>`<button data-nav="${id}" class="${route===id?'active':''}" title="${l}">${icon(ic)}<span>${l}</span>${id==='reviews'?`<span class="count">${reviewCount}</span>`:''}</button>`).join('')}</nav><div class="side-note">${icon('leaf')}<br><strong>Cùng nhau, làm tốt hơn.</strong><p>Mỗi đầu việc rõ ràng.<br>Mỗi đóng góp được ghi nhận.</p></div><div class="profile">${avatar(currentUser.id)}<span><strong>${esc(currentUser.name)}</strong><small>${roleNames[currentUser.role]}</small></span><button data-account title="Đổi mật khẩu">${icon('lock')}</button></div></aside><div class="shell"><header><div class="header-path">Không gian làm việc<span>/</span><strong>${navs().find(n=>n[0]===route)?.[2]||'Tổng quan'}</strong></div><div class="header-right"><span class="live"><i></i>Dữ liệu dùng chung</span><button class="icon-btn" id="refresh" title="Làm mới dữ liệu">${icon('refresh')}</button><button class="icon-btn" data-account title="Tài khoản của tôi">${avatar(currentUser.id)}</button><button class="icon-btn" id="logout" title="Đăng xuất">${icon('logout')}</button></div></header><main id="app"></main><footer><span>SUPER NET · CONTENT WORKSPACE</span><span>Rõ công việc. Vững tiến độ. Cùng phát triển.</span></footer></div>`;
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
 document.querySelectorAll('[data-account]').forEach(b=>b.onclick=accountModal);
 $('#refresh').onclick=async()=>{try{await refresh();toast('Đã lấy dữ liệu mới nhất.')}catch(e){toast(e.message)}};
 $('#logout').onclick=async()=>{try{await api('/logout','POST',{});csrf='';currentUser=null;data={users:[],tasks:[],reports:[]};authPage(false)}catch(e){toast(e.message)}};
 const pages={overview, tasks:tasksPage,mine:tasksPage,calendar:calendarPage,reviews:reviewsPage,team:teamPage,reports:reportsPage};(pages[route]||overview)();bindCommon();
}
function heading(kicker,title,sub,create=false,extra=''){return `<div class="page-title"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${extra}${create&&manager()?`<button class="primary" data-create>${icon('plus')}Tạo nội dung</button>`:''}</div></div>`}
function statCards(ts=data.tasks){return `<div class="stats">${[['all','Nội dung trong kế hoạch',ts.length,'tasks',''],['done','Đã nghiệm thu',ts.filter(t=>t.status==='done').length,'check',''],['review','Chờ phê duyệt',ts.filter(t=>t.status==='review').length,'clock','gold'],['late','Đang quá hạn',ts.filter(overdue).length,'flag','red']].map(([f,l,n,i,c])=>`<button class="stat ${c}" data-stat="${f}"><span class="stat-top">${l}${icon(i)}</span><strong>${String(n).padStart(2,'0')}</strong><small>${f==='all'?'Trong phạm vi bạn phụ trách':f==='done'?'Đầu ra đã được xác nhận':f==='review'?'Đã bàn giao, chờ kiểm tra':'Cần thống nhất hướng xử lý'}</small></button>`).join('')}</div>`}
function empty(title,sub,create=false){return `<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${sub}</p>${create&&manager()?'<button class="primary" data-create>＋ Tạo nội dung đầu tiên</button>':''}</div>`}
function overview(){
 const ts=data.tasks,needs=ts.filter(t=>active(t)&&t.due<=today()),blocked=ts.filter(t=>active(t)&&t.blocker),firstName=currentUser.name.trim().split(/\s+/).slice(-2).join(' ');
 $('#app').innerHTML=heading('WORKSPACE OVERVIEW',manager()?'Tổng quan đội ngũ':'Không gian của bạn','Nắm rõ tiến độ, phối hợp nhịp nhàng và không bỏ lỡ công việc.',true)+`<section class="hero"><div><div class="hero-tag">MỘT NGÀY MỚI · ${fmt(today(),true)}</div><h2>Chào ${esc(firstName)}, cùng làm tốt hôm nay.</h2><p>${ts.length?`Có <b>${needs.length} nội dung đến hạn cần chú ý</b> và <b>${ts.filter(t=>t.status==='review').length} nội dung đang chờ duyệt</b>.<br>Kiểm tra bước tiếp theo, cập nhật tiến độ và chia sẻ điều cần hỗ trợ.`:'Bắt đầu từ một kế hoạch rõ ràng. Giao đúng người, theo dõi từng khâu và ghi nhận kết quả cùng nhau.'}</p></div><div class="hero-art"><div class="hero-sheet"><b></b>✓ &nbsp; Lên kế hoạch<br>✓ &nbsp; Cùng thực hiện<br>○ &nbsp; Đạt mục tiêu</div><div class="hero-check">✓</div></div></section>`+statCards()+`${manager()&&data.users.filter(u=>u.active).length===1?'<div class="info-note">Bắt đầu với đội ngũ của bạn: tạo tài khoản cho nhân viên và thực tập sinh, rồi giao các khâu sản xuất. <button class="text-btn" data-team>Thêm thành viên →</button></div>':''}<div class="grid"><div><section class="panel"><div class="panel-head"><div><h2>Công việc cần theo dõi</h2><p>Ưu tiên việc đang mở và các mốc bàn giao gần nhất.</p></div><button class="text-btn" data-all>Xem tất cả ↗</button></div>${tabs()}${table(filtered(ts).sort((a,b)=>Number(active(b))-Number(active(a))||a.due.localeCompare(b.due)).slice(0,6))}<div class="panel-foot">${ts.length} nội dung · Tiến độ tính theo 3 khâu kịch bản, quay, dựng</div></section><section class="panel"><div class="panel-head"><div><h2>Tiến độ sản xuất</h2><p>Tổng hợp các khâu của nội dung đang mở.</p></div></div>${['script','shoot','edit'].map(key=>{const stages=ts.filter(active).flatMap(t=>t.stages.filter(s=>s.key===key));const n=stages.filter(s=>s.status==='done').length;return `<div class="team-row"><div class="team-line"><span>${stageNames[key]}</span><small>${n}/${stages.length} đã bàn giao</small></div>${bar(n/Math.max(stages.length,1)*100)}</div>`}).join('')}</section></div><div class="right-column"><section class="panel"><div class="panel-head"><h2>Điểm cần chú ý</h2>${icon('flag')}</div><div class="notice red">${icon('clock')}<div><strong>${ts.filter(overdue).length} nội dung đang quá hạn</strong><p>Kiểm tra nguyên nhân và thời điểm bàn giao tiếp theo.</p><button class="text-btn" data-late>Xem công việc →</button></div></div><div class="notice">${icon('flag')}<div><strong>${blocked.length} nội dung cần hỗ trợ</strong><p>${esc(blocked[0]?.blocker||'Chưa có vướng mắc được ghi nhận.')}</p>${blocked.length?`<button class="text-btn" data-task="${esc(blocked[0].id)}">Xem vướng mắc →</button>`:''}</div></div></section><section class="panel"><div class="panel-head"><div><h2>${manager()?'Khối lượng đội ngũ':'Phần việc của bạn'}</h2><p>Số khâu chưa bàn giao trên từng người.</p></div></div>${(manager()?data.users.filter(u=>u.active).slice(0,5):[currentUser]).map(u=>capacityRow(u)).join('')}<div class="panel-foot">Thống kê để điều phối, không dùng chấm năng suất.</div></section><section class="panel"><div class="panel-head"><div><h2>Ghi nhận bước tiến mỗi ngày.</h2><p>Gửi kết quả hôm nay và ưu tiên tiếp theo.</p><button class="text-btn" data-reports style="margin-top:12px">Viết báo cáo →</button></div></div></section></div></div>`;
}
function capacityRow(u){const ss=data.tasks.filter(active).flatMap(t=>t.stages.filter(s=>s.ownerId===u.id));const done=ss.filter(s=>s.status==='done').length;return `<div class="team-row"><div class="team-line">${person(u.id)}<small>${ss.length-done} khâu đang mở</small></div>${bar(done/Math.max(ss.length,1)*100)}</div>`}
function matches(t,status){return status==='all'||(status==='late'?overdue(t):status==='blocked'?active(t)&&!!t.blocker:t.status===status)}
function filtered(ts=data.tasks){return ts.filter(t=>(route!=='mine'||own(t))&&matches(t,filters.status)&&(!filters.owner||String(t.ownerId)===String(filters.owner)||t.stages.some(s=>String(s.ownerId)===String(filters.owner)))&&(!filters.channel||t.channel===filters.channel)&&(!filters.search||[t.title,t.id,t.series,t.nextStep,t.channel].join(' ').toLocaleLowerCase('vi').includes(filters.search.toLocaleLowerCase('vi')))).sort((a,b)=>Number(active(b))-Number(active(a))||a.due.localeCompare(b.due))}
function tabs(){return `<div class="tabs">${[['all','Tất cả'],['doing','Đang làm'],['review','Chờ duyệt'],['late','Quá hạn'],['blocked','Có vướng mắc']].map(([f,l])=>`<button data-filter="${f}" class="${filters.status===f?'selected':''}">${l}<small>${data.tasks.filter(t=>(route!=='mine'||own(t))&&matches(t,f)).length}</small></button>`).join('')}</div>`}
function table(ts){return ts.length?`<div class="table-wrap"><table><thead><tr><th>NỘI DUNG / KÊNH</th><th>PHỤ TRÁCH</th><th>HẠN BÀN GIAO</th><th>SẢN XUẤT</th><th>TRẠNG THÁI</th></tr></thead><tbody>${ts.map(t=>`<tr tabindex="0" role="button" data-task="${esc(t.id)}" aria-label="Mở ${esc(t.title)}"><td><div class="task-title">${esc(t.title)}</div><span class="task-sub">${esc(t.channel||'Chưa chọn kênh')} · ${esc(t.pillar||'Chưa phân loại')} ${t.series?'· '+esc(t.series):''}</span>${t.nextStep&&active(t)?`<span class="task-sub next-step">Tiếp theo: ${esc(t.nextStep)}</span>`:''}${t.blocker&&active(t)?'<span class="task-sub late">⚑ Đang có vướng mắc</span>':''}</td><td>${person(t.ownerId)}</td><td class="${overdue(t)?'late':''}">${fmt(t.due)}<span class="task-sub ${overdue(t)?'late':''}">${overdue(t)?'Quá hạn':priorities[t.priority]+' ưu tiên'}</span></td><td><div class="progress">${bar(progress(t))}${progress(t)}%</div><span class="task-sub">${t.stages.filter(s=>s.status==='done').length}/3 khâu bàn giao</span></td><td>${badge(t.status)}<span class="task-sub">${pubNames[t.publicationStatus]}</span></td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có nội dung trong mục này',manager()?'Tạo nội dung và giao các khâu cho thành viên.':'Công việc được giao sẽ xuất hiện ở đây.',true)}
function tasksPage(){const channels=[...new Set(data.tasks.map(t=>t.channel).filter(Boolean))];$('#app').innerHTML=heading('CONTENT PRODUCTION',route==='mine'?'Việc của tôi':'Kế hoạch nội dung',route==='mine'?'Các nội dung và khâu sản xuất được giao cho bạn.':'Từ ý tưởng đến bài đăng — rõ người, rõ hạn, rõ đầu ra.',true)+`<div class="filters"><input id="task-search" aria-label="Tìm nội dung" placeholder="Tìm tiêu đề, series, bước tiếp theo…" value="${esc(filters.search)}"><select id="owner-filter" aria-label="Lọc nhân viên"><option value="">Tất cả thành viên</option>${userOpts(filters.owner)}</select><select id="channel-filter" aria-label="Lọc kênh"><option value="">Tất cả kênh</option>${opts(channels.map(c=>[c,c]),filters.channel)}</select><select id="status-filter" aria-label="Lọc trạng thái">${opts([['all','Tất cả trạng thái'],...Object.entries(statusNames),['late','Quá hạn'],['blocked','Có vướng mắc']],filters.status)}</select><button id="view-toggle">${icon(taskView==='list'?'grid':'tasks')}${taskView==='list'?'Bảng trạng thái':'Danh sách'}</button></div><section class="panel">${tabs()}<div id="task-results">${taskResults()}</div></section>`;
 $('#task-search').oninput=e=>{filters.search=e.target.value;$('#task-results').innerHTML=taskResults();bindTasks()};
 [['owner-filter','owner'],['channel-filter','channel'],['status-filter','status']].forEach(([id,key])=>$('#'+id).onchange=e=>{filters[key]=e.target.value;render()});
 $('#view-toggle').onclick=()=>{taskView=taskView==='list'?'board':'list';render()};
}
function taskResults(){const ts=filtered();if(taskView==='list')return table(ts);return `<div class="board" style="padding:18px">${[['pending','Chờ bắt đầu'],['doing','Đang xử lý'],['review','Chờ duyệt'],['done','Đã nghiệm thu']].map(([s,l])=>`<div class="column"><h3>${l}</h3>${ts.filter(t=>s==='doing'?['doing','revision'].includes(t.status):t.status===s).map(t=>`<div class="task-card" tabindex="0" role="button" data-task="${esc(t.id)}"><span class="task-sub">${esc(t.channel)} · ${esc(priorities[t.priority])}</span><h4>${esc(t.title)}</h4>${badge(t.status)}<div class="progress">${bar(progress(t))}${progress(t)}%</div>${person(t.ownerId)}<span class="task-sub ${overdue(t)?'late':''}">Hạn bàn giao ${fmt(t.due)}${t.blocker?' · Có vướng mắc':''}</span></div>`).join('')||'<p style="font-size:11px;text-align:center">Chưa có nội dung</p>'}</div>`).join('')}</div>${ts.some(t=>t.status==='cancelled')?'<div class="panel-foot">Nội dung đã hủy được xem trong chế độ danh sách.</div>':''}`}
function bindTasks(){document.querySelectorAll('[data-task]').forEach(e=>{e.onclick=()=>taskModal(e.dataset.task);e.onkeydown=ev=>{if(ev.key==='Enter'){ev.preventDefault();taskModal(e.dataset.task)}}})}
function bindCommon(){bindTasks();document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>navigate('team'));document.querySelectorAll('[data-create]').forEach(b=>b.onclick=createTask);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filters.status=b.dataset.filter;render()});document.querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>{route='tasks';filters.status=b.dataset.stat;render()});document.querySelectorAll('[data-all]').forEach(b=>b.onclick=()=>navigate('tasks'));document.querySelectorAll('[data-late]').forEach(b=>b.onclick=()=>{route='tasks';filters.status='late';render()});document.querySelectorAll('[data-reports]').forEach(b=>b.onclick=()=>navigate('reports'))}
function openModal(content,small=false){previousFocus=document.activeElement;$('#overlay').innerHTML=`<section class="modal ${small?'small':''}" role="dialog" aria-modal="true" aria-label="Chi tiết và cập nhật">${content}</section>`;$('#overlay').classList.remove('hidden');document.body.style.overflow='hidden';$('#overlay').querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);$('#overlay').onclick=e=>{if(e.target===$('#overlay'))closeModal()};setTimeout(()=>$('#overlay').querySelector('input:not(:disabled),select:not(:disabled),button')?.focus(),0)}
function closeModal(){$('#overlay').classList.add('hidden');$('#overlay').innerHTML='';document.body.style.overflow='';previousFocus?.isConnected&&previousFocus.focus()}
document.addEventListener('keydown',e=>{if($('#overlay').classList.contains('hidden'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...$('#overlay').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function modalHead(title){return `<div class="modal-head"><h2>${title}</h2><button type="button" data-close aria-label="Đóng">${icon('close')}</button></div>`}
function createTask(){if(!manager())return;
 const def=data.users.find(u=>u.active&&u.role==='content')||currentUser;
 openModal(modalHead('Tạo nội dung mới')+`<p class="modal-subtitle">Một nội dung, một người chịu trách nhiệm chính. Mỗi khâu có thể giao cho một thành viên khác nhau.</p><form id="create-form"><div class="form-grid">${field('Tiêu đề / chủ đề *','<input name="title" required maxlength="200" placeholder="Ví dụ: Video hướng dẫn sử dụng SafeStraps">',true)}${field('Kênh *','<input name="channel" required maxlength="100" placeholder="Safestraps Official">')}${field('Nhóm nội dung (Pillar)',`<select name="pillar">${opts(['PRODUCT','BRANDING','TRUST','ENTERTAINMENT','PROMOTION','EDUCATE','SALE'].map(v=>[v,v]))}</select>`)}${field('Góc khai thác (Angle)','<input name="angle" maxlength="150" placeholder="UGC, so sánh, USP/Review…">')}${field('Series / tập','<input name="series" maxlength="150" placeholder="Tặng dây ràng 0đ · Tập 95">')}${field('Chiến dịch','<input name="campaign" maxlength="150" placeholder="Ví dụ: Chiến dịch 11.11">')}${field('Ưu tiên',`<select name="priority">${opts(Object.entries(priorities),'normal')}</select>`)}${field('Phụ trách chính',`<select name="ownerId">${userOpts(def.id)}</select>`)}${field('Người duyệt',`<select name="reviewerId">${userOpts(currentUser.id,true)}</select>`)}${field('Hạn bàn giao *',`<input name="due" type="date" value="${dateAdd(today(),3)}" required>`)}${field('Thời lượng dự kiến (giờ)','<input name="estimatedHours" type="number" min="0.5" max="1000" step="0.5" value="4" required>')}${field('Yêu cầu & sản phẩm phải nộp *','<textarea name="description" required maxlength="10000" placeholder="Mục tiêu, thông điệp, định dạng và số lượng sản phẩm…"></textarea>',true)}${field('Tiêu chí nghiệm thu *','<textarea name="criteria" required maxlength="10000" placeholder="Thông tin chính xác, đủ cảnh, rõ phụ đề, đúng thông điệp…"></textarea>',true)}${field('Bước tiếp theo *','<input name="nextStep" required maxlength="1000" placeholder="Hành động cần thực hiện trước tiên">',true)}</div><h3 class="section-title">Phân công các khâu sản xuất</h3>${['script','shoot','edit'].map((key,i)=>`<div class="stage"><div class="stage-head"><strong>0${i+1} · ${stageNames[key]}</strong></div><div class="form-grid">${field('Người thực hiện',`<select name="stage_${key}_owner">${userOpts(def.id)}</select>`)}${field('Hạn khâu này *',`<input name="stage_${key}_due" type="date" value="${dateAdd(today(),i+1)}" required>`)}</div></div>`).join('')}<div class="form-actions"><button type="button" data-close>Hủy</button><button class="primary">Tạo & giao việc</button></div></form>`);
 $('#create-form').onsubmit=e=>{e.preventDefault();runForm(e.target,async()=>{const f=Object.fromEntries(new FormData(e.target));const stages=['script','shoot','edit'].map(key=>({key,label:stageNames[key],ownerId:f[`stage_${key}_owner`],due:f[`stage_${key}_due`],status:'todo',note:''}));for(const s of stages){delete f[`stage_${s.key}_owner`];delete f[`stage_${s.key}_due`];if(s.due>f.due)throw Error('Hạn từng khâu không được sau hạn bàn giao nội dung.')}f.estimatedHours=Number(f.estimatedHours);await api('/tasks','POST',{...f,stages});closeModal();await refresh();toast('Đã tạo nội dung và giao các khâu sản xuất.')})};
}
function taskModal(id){
 const t=data.tasks.find(t=>String(t.id)===String(id));if(!t)return;
 const locked=['done','cancelled'].includes(t.status), editable=!locked&&(manager()||own(t));
 const settings=manager()&&!locked?`<details><summary class="text-btn">Chỉnh sửa kế hoạch & phân công</summary><div class="form-grid" style="margin-top:18px">${field('Tiêu đề *',`<input name="title" value="${esc(t.title)}" required maxlength="240">`,true)}${field('Kênh',`<input name="channel" value="${esc(t.channel)}" maxlength="240">`)}${field('Pillar',`<input name="pillar" value="${esc(t.pillar)}" maxlength="240">`)}${field('Angle',`<input name="angle" value="${esc(t.angle)}" maxlength="240">`)}${field('Series / tập',`<input name="series" value="${esc(t.series)}" maxlength="240">`)}${field('Chiến dịch',`<input name="campaign" value="${esc(t.campaign)}" maxlength="240">`)}${field('Ưu tiên',`<select name="priority">${opts(Object.entries(priorities),t.priority)}</select>`)}${field('Phụ trách chính',`<select name="ownerId">${userOpts(t.ownerId)}</select>`)}${field('Người duyệt',`<select name="reviewerId">${userOpts(t.reviewerId,true)}</select>`)}${field('Hạn bàn giao',`<input name="due" type="date" value="${t.due}" required>`)}${field('Giờ dự kiến',`<input name="estimatedHours" type="number" min="0.5" max="1000" step="0.5" value="${t.estimatedHours}" required>`)}${field('Yêu cầu *',`<textarea name="description" required maxlength="12000">${esc(t.description)}</textarea>`,true)}${field('Tiêu chí nghiệm thu *',`<textarea name="criteria" required maxlength="8000">${esc(t.criteria)}</textarea>`,true)}</div></details>`:'';
 openModal(modalHead(esc(t.title))+`<div class="pill-row">${badge(t.status)}${badge(t.publicationStatus,pubNames)}<span class="status">${priorities[t.priority]} ưu tiên</span>${overdue(t)?'<span class="status s-blocked">Quá hạn</span>':''}</div><div class="detail-summary"><div><small>Phụ trách chính</small>${esc(user(t.ownerId).name)}</div><div><small>Người duyệt</small>${esc(user(t.reviewerId).name)}</div><div><small>Hạn ban đầu → hiện tại</small>${fmt(t.originalDue,true)} → ${fmt(t.due,true)}</div><div><small>Kênh · Pillar · Series</small>${esc([t.channel,t.pillar,t.series].filter(Boolean).join(' · ')||'Chưa đặt')}</div></div><h3>Yêu cầu & sản phẩm bàn giao</h3><p class="brief">${esc(t.description)}</p><h3>Tiêu chí nghiệm thu</h3><p class="brief">${esc(t.criteria)}</p><form id="task-update">${settings}<h3 class="section-title">Tiến độ sản xuất · ${progress(t)}%</h3>${bar(progress(t))}${t.stages.map((s,i)=>{const allowed=editable&&(manager()||s.ownerId===currentUser.id);return `<div class="stage"><div class="stage-head"><strong>0${i+1} · ${stageNames[s.key]}</strong>${badge(s.status,stageStatus)}</div><div class="stage-meta"><span>${esc(user(s.ownerId).name)}</span><span class="${s.status!=='done'&&s.due<today()&&!locked?'late':''}">Hạn ${fmt(s.due)}</span></div><div class="form-grid" style="margin-top:12px">${manager()&&!locked?field('Người thực hiện',`<select name="stage_${s.key}_owner">${userOpts(s.ownerId)}</select>`)+field('Hạn khâu',`<input name="stage_${s.key}_due" type="date" value="${s.due}" required>`):''}${field('Trạng thái',`<select name="stage_${s.key}_status" ${allowed?'':'disabled'}>${opts(Object.entries(stageStatus),s.status)}</select>`)}${field('Ghi chú / đường dẫn đầu ra khâu',`<textarea name="stage_${s.key}_note" maxlength="4000" ${allowed?'':'disabled'} placeholder="Đã làm gì, file nào, bước cần bàn giao…">${esc(s.note)}</textarea>`,true)}</div></div>`}).join('')}<h3 class="section-title">Cập nhật & bàn giao</h3><div class="form-grid">${field('Bước tiếp theo',`<input name="nextStep" maxlength="4000" value="${esc(t.nextStep)}" ${editable?'':'disabled'}>`,true)}${field('Link kịch bản',`<input name="scriptUrl" type="url" value="${esc(t.scriptUrl)}" ${editable?'':'disabled'} placeholder="https://…">`,true)}${field('Link sản phẩm / minh chứng bàn giao',`<input name="evidence" type="url" value="${esc(t.evidence)}" ${editable?'':'disabled'} placeholder="https://…">`,true)}${field('Vướng mắc & hỗ trợ cần thiết',`<textarea name="blocker" maxlength="4000" ${editable?'':'disabled'} placeholder="Nguyên nhân, người hỗ trợ và hạn xử lý. Xóa nội dung khi đã giải quyết.">${esc(t.blocker)}</textarea>`,true)}</div><div class="pill-row">${safeLink(t.scriptUrl,'Mở kịch bản')}${safeLink(t.evidence,'Mở sản phẩm bàn giao')}</div>${!locked?field('Phản hồi duyệt / lý do hủy',`<textarea name="actionNote" maxlength="4000" placeholder="Bắt buộc khi yêu cầu sửa hoặc hủy công việc…"></textarea>`,true):''}<div class="form-actions">${editable?'<button type="submit">Lưu cập nhật</button>':''}${['pending','revision'].includes(t.status)?'<button type="button" class="primary" data-action="start">Nhận & bắt đầu</button>':''}${['doing','revision'].includes(t.status)?'<button type="button" class="primary" data-action="submit">Nộp duyệt</button>':''}${t.status==='review'&&canReview(t)?'<button type="button" data-action="request_changes">Yêu cầu sửa</button><button type="button" class="primary" data-action="approve">Nghiệm thu</button>':''}${manager()&&!locked?'<button type="button" class="danger" data-action="cancel">Hủy nội dung</button>':''}</div></form>${t.status==='done'?`<h3 class="section-title">Lịch đăng & xuất bản</h3><p class="modal-subtitle">Sản xuất đã được nghiệm thu. Theo dõi việc lên lịch và đăng bài riêng.</p><form id="publish-form"><div class="form-grid">${field('Trạng thái đăng',`<select name="publicationStatus" ${canPublish(t)?'':'disabled'}>${opts(Object.entries(pubNames),t.publicationStatus)}</select>`)}${field('Ngày giờ đăng (giờ Việt Nam)',`<input name="publishAt" type="datetime-local" value="${esc(t.publishAt.slice(0,16))}" ${canPublish(t)?'':'disabled'}>`)}${field('Link bài đã đăng',`<input name="publishUrl" type="url" value="${esc(t.publishUrl)}" ${canPublish(t)?'':'disabled'} placeholder="https://www.tiktok.com/…">`,true)}</div>${safeLink(t.publishUrl,'Mở bài đăng')}${canPublish(t)?'<div class="form-actions"><button class="primary">Lưu thông tin đăng bài</button></div>':''}</form>`:''}<h3 class="section-title">Lịch sử cập nhật</h3>${t.history.map(h=>`<div class="history"><strong>${esc(h.actor)}</strong> · ${esc(h.action)}<time>${fmtTime(h.at)}</time></div>`).join('')}`);
 function changes(){
  const f=Object.fromEntries(new FormData($('#task-update'))), body={version:t.version};
  if(!editable)return body;
  for(const key of ['nextStep','blocker','evidence','scriptUrl'])body[key]=f[key]||'';
  if(manager())for(const key of ['title','channel','pillar','angle','series','campaign','priority','ownerId','reviewerId','due','estimatedHours','description','criteria'])body[key]=f[key];
  body.stages=t.stages.map(s=>{const next={...s};if(manager()){next.ownerId=Number(f[`stage_${s.key}_owner`]);next.due=f[`stage_${s.key}_due`]}if(manager()||s.ownerId===currentUser.id){next.status=f[`stage_${s.key}_status`];next.note=f[`stage_${s.key}_note`]}return next});
  return body;
 }
 $('#task-update').onsubmit=e=>{e.preventDefault();runForm(e.target,async()=>{await api('/tasks/'+t.id,'PATCH',changes());closeModal();await refresh();toast('Đã lưu tiến độ lên dữ liệu chung.')})};
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const form=$('#task-update');if(!form.reportValidity())return;runForm(form,async()=>{const note=form.elements.actionNote?.value||'';if(['request_changes','cancel'].includes(b.dataset.action)&&!note.trim())throw Error('Hãy nhập phản hồi cần sửa hoặc lý do hủy.');const updated=editable?await api('/tasks/'+t.id,'PATCH',changes()):t;t.version=updated.version;await api('/tasks/'+t.id+'/action','POST',{version:t.version,action:b.dataset.action,note});closeModal();await refresh();toast('Đã cập nhật trạng thái công việc.')})});
 const pub=$('#publish-form');if(pub)pub.onsubmit=e=>{e.preventDefault();runForm(pub,async()=>{const f=Object.fromEntries(new FormData(pub));if(f.publishAt)f.publishAt+=':00+07:00';await api('/tasks/'+t.id,'PATCH',{version:t.version,...f});closeModal();await refresh();toast('Đã lưu lịch đăng và minh chứng xuất bản.')})};
}
function safeLink(url,label){try{if(!['http:','https:'].includes(new URL(url).protocol))return '';return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" class="text-btn">${label} ↗</a>`}catch{return ''}}
function reviewsPage(){const ts=data.tasks.filter(t=>t.status==='review');$('#app').innerHTML=heading('REVIEW & APPROVAL','Hàng chờ phê duyệt','Kiểm tra sản phẩm, phản hồi cụ thể và nghiệm thu đầu ra.')+`<section class="panel"><div class="panel-head"><div><h2>${ts.length} nội dung chờ kiểm tra</h2><p>${ts.filter(canReview).length} nội dung bạn được quyền duyệt · Người được phân công duyệt hoặc quản trị viên có thể nghiệm thu.</p></div></div>${table(ts)}</section>`}
function calendarPage(){const start=dateAdd(monday(today()),calendarOffset*7),end=dateAdd(start,6);$('#app').innerHTML=heading('EDITORIAL CALENDAR','Lịch nội dung','Theo dõi hạn sản xuất và lịch đăng trong cùng một tuần.',true)+`<div class="filters"><button id="week-prev">← Tuần trước</button><button id="week-now">Tuần này</button><button id="week-next">Tuần sau →</button><span style="padding:11px 0;color:#8a9a79">${fmt(start)} – ${fmt(end,true)}</span></div><div class="info-note">Mốc “Bàn giao” là hạn sản xuất; mốc “Đăng bài” lấy từ lịch đăng sau nghiệm thu. Các khâu viết, quay, dựng được xem trong chi tiết nội dung.</div><section class="panel"><div class="table-wrap"><div class="calendar">${Array.from({length:7},(_,i)=>{const d=dateAdd(start,i),due=data.tasks.filter(t=>t.due===d&&t.status!=='cancelled'),pub=data.tasks.filter(t=>t.publishAt.slice(0,10)===d&&t.publicationStatus!=='unscheduled');return `<div class="day ${d===today()?'today':''}"><h3>${['Thứ hai','Thứ ba','Thứ tư','Thứ năm','Thứ sáu','Thứ bảy','Chủ nhật'][i]}<strong>${d.slice(8)}</strong></h3>${due.map(t=>`<button class="calendar-task" data-task="${t.id}"><small class="${overdue(t)?'late':''}">BÀN GIAO · ${esc(user(t.ownerId).name)}</small>${esc(t.title)}<span class="task-sub">${statusNames[t.status]}</span></button>`).join('')}${pub.map(t=>`<button class="calendar-task" data-task="${t.id}" style="background:#eef5e7"><small>ĐĂNG BÀI · ${esc(t.channel)}</small>${esc(t.title)}<span class="task-sub">${pubNames[t.publicationStatus]}</span></button>`).join('')}</div>`}).join('')}</div></div></section>`;$('#week-prev').onclick=()=>{calendarOffset--;render()};$('#week-next').onclick=()=>{calendarOffset++;render()};$('#week-now').onclick=()=>{calendarOffset=0;render()}}
function teamPage(){if(!manager())return;$('#app').innerHTML=heading('PEOPLE & PERMISSIONS','Đội ngũ Content Marketing','Mỗi thành viên một tài khoản, đúng quyền và đúng phần việc.',false,`<button id="export" title="Xuất dữ liệu dùng đối chiếu, không thay thế sao lưu database">${icon('download')}Xuất dữ liệu</button><button class="primary" id="add-user">${icon('plus')}Thêm thành viên</button>`)+`<div class="info-note">Quản trị viên quản lý toàn bộ tài khoản. Trưởng nhóm giao việc, duyệt đầu ra và quản lý nhân viên Content / thực tập sinh. Thành viên chỉ cập nhật phần được giao và gửi báo cáo cá nhân.</div><div class="cards">${data.users.map(u=>{const tasks=data.tasks.filter(t=>t.ownerId===u.id||t.stages.some(s=>s.ownerId===u.id)),stages=tasks.filter(active).flatMap(t=>t.stages.filter(s=>s.ownerId===u.id));const open=stages.filter(s=>s.status!=='done').length;return `<section class="panel member">${avatar(u.id)}<h3>${esc(u.name)}</h3><p>${esc(u.username||'')}</p><div class="pill-row"><span class="status">${roleNames[u.role]}</span>${!u.active?'<span class="status s-cancelled">Đã khóa</span>':''}</div><p>${tasks.filter(active).length} nội dung đang mở · ${tasks.filter(overdue).length} quá hạn</p>${bar((stages.length-open)/Math.max(stages.length,1)*100)}<p>${open} khâu cần bàn giao</p><p class="muted">Năng lực dự kiến: ${u.capacity} giờ / tuần</p><div class="actions"><button class="text-btn" data-person="${u.id}">Xem công việc →</button>${currentUser.role==='admin'||['content','intern'].includes(u.role)?`<button class="text-btn" data-user="${u.id}">Sửa tài khoản</button>`:''}</div></section>`}).join('')}</div>`;$('#add-user').onclick=()=>userModal();$('#export').onclick=async()=>{try{download('supernet-'+today()+'.json',await api('/export'));toast('Đã xuất dữ liệu. Để sao lưu phục hồi, hãy sao chép thư mục data khi server đã dừng.')}catch(e){toast(e.message)}};document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{route='tasks';filters.owner=b.dataset.person;render()});document.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>userModal(Number(b.dataset.user)))}
function userModal(id){const u=id?user(id):null;const roles=currentUser.role==='admin'?Object.entries(roleNames):Object.entries(roleNames).filter(([r])=>['content','intern'].includes(r));openModal(modalHead(u?'Chỉnh sửa thành viên':'Thêm thành viên')+`<p class="modal-subtitle">Cấp tài khoản riêng để ghi nhận đúng người thực hiện và báo cáo. Mật khẩu cần ít nhất 10 ký tự.</p><form id="user-form"><div class="form-grid">${field('Họ và tên *',`<input name="name" required maxlength="120" value="${esc(u?.name||'')}" autocomplete="off">`,true)}${!u?field('Tên đăng nhập *','<input name="username" required pattern="[a-zA-Z0-9][a-zA-Z0-9._@+\\-]{2,59}" maxlength="60" minlength="3" autocomplete="off" placeholder="Ví dụ: thuy.dung">',true,'Chữ không dấu, số hoặc dấu chấm; không có khoảng trắng.'):''}${field('Vai trò',`<select name="role">${opts(roles,u?.role||'content')}</select>`)}${field('Năng lực dự kiến (giờ / tuần)',`<input name="capacity" required type="number" min="1" max="168" step="0.5" value="${u?.capacity||40}">`)}${u?field('Trạng thái tài khoản',`<select name="active">${opts([['1','Đang hoạt động'],['0','Khóa tài khoản']],u.active?'1':'0')}</select>`,true):''}${field(u?'Đặt lại mật khẩu (để trống nếu giữ nguyên)':'Mật khẩu ban đầu *',`<input name="password" type="password" minlength="10" maxlength="256" ${u?'':'required'} autocomplete="new-password">`,true)}</div><p class="role-description">Nhân viên và thực tập sinh có cùng quyền cập nhật phần việc được giao. Trưởng nhóm không thể cấp quyền quản trị hoặc sửa tài khoản quản trị.</p><div class="form-actions"><button type="button" data-close>Hủy</button><button class="primary">${u?'Lưu thay đổi':'Tạo tài khoản'}</button></div></form>`,true);$('#user-form').onsubmit=e=>{e.preventDefault();runForm(e.target,async()=>{const f=Object.fromEntries(new FormData(e.target));f.capacity=Number(f.capacity);if(u){f.active=f.active==='1';if(!f.password)delete f.password}await api('/users'+(u?'/'+u.id:''),u?'PATCH':'POST',f);closeModal();await refresh();toast(u?'Đã cập nhật tài khoản.':'Đã tạo tài khoản cho thành viên.')})}}
function accountModal(){openModal(modalHead('Tài khoản của tôi')+`<p class="modal-subtitle">${esc(currentUser.name)} · ${roleNames[currentUser.role]}<br>Tên đăng nhập: ${esc(currentUser.username)}</p><form id="password-form">${field('Mật khẩu hiện tại','<input name="currentPassword" type="password" required autocomplete="current-password">')}${field('Mật khẩu mới','<input name="newPassword" type="password" required minlength="10" maxlength="256" autocomplete="new-password">')}${field('Nhập lại mật khẩu mới','<input name="confirm" type="password" required minlength="10" autocomplete="new-password">')}<p style="font-size:11px;margin-top:14px">Đổi mật khẩu sẽ đăng xuất các phiên của tài khoản này.</p><div class="form-actions"><button type="button" data-close>Hủy</button><button class="primary">Đổi mật khẩu</button></div></form>`,true);$('#password-form').onsubmit=e=>{e.preventDefault();runForm(e.target,async()=>{const f=Object.fromEntries(new FormData(e.target));if(f.newPassword!==f.confirm)throw Error('Mật khẩu nhập lại chưa khớp.');delete f.confirm;await api('/password','POST',f);closeModal();csrf='';currentUser=null;authPage(false);toast('Đã đổi mật khẩu. Hãy đăng nhập lại.')})}}
function reportsPage(){
 if(!reportPeriod)reportPeriod=today();if(reportKind==='weekly')reportPeriod=monday(reportPeriod);
 const end=reportKind==='weekly'?dateAdd(reportPeriod,6):reportPeriod;
 const selectedOwner=reportOwner?Number(reportOwner):currentUser.id;
 const reports=data.reports.filter(r=>r.kind===reportKind&&r.period===reportPeriod&&(!reportOwner||r.ownerId===selectedOwner));
 const submitted=data.reports.some(r=>r.kind===reportKind&&r.period===reportPeriod&&r.ownerId===currentUser.id);
 $('#app').innerHTML=heading('DAILY & WEEKLY REFLECTION','Báo cáo tiến độ','Tổng hợp từ công việc thực tế. Ghi rõ kết quả, vướng mắc và bước tiếp theo.')+`<div class="filters"><select id="report-kind" aria-label="Loại báo cáo">${opts([['daily','Báo cáo ngày'],['weekly','Báo cáo tuần']],reportKind)}</select><input id="report-period" type="date" aria-label="Ngày hoặc tuần báo cáo" value="${reportPeriod}" style="flex:0;min-width:155px">${manager()?`<select id="report-owner" aria-label="Lọc người báo cáo"><option value="">Tất cả báo cáo · xem số liệu của tôi</option>${userOpts(reportOwner)}</select>`:''}<button id="export-reports">${icon('download')}Xuất báo cáo</button></div><div class="info-note">Kỳ ${reportKind==='weekly'?'tuần':'ngày'}: <strong>${fmt(reportPeriod,true)}${reportKind==='weekly'?' – '+fmt(end,true):''}</strong>. Số liệu bên dưới là nội dung có hạn bàn giao trong kỳ, thuộc người phụ trách chính hoặc người được giao khâu; không phải số việc đã làm trong ngày. Mỗi người gửi một bản/kỳ và bản đã gửi giữ nguyên.</div><div id="report-summary">${reportSummary?summaryCards(reportSummary):'<p style="padding:15px;color:#8c9b7e">Đang tổng hợp số liệu…</p>'}</div><div class="grid"><section class="panel"><div class="panel-head"><div><h2>Báo cáo của tôi</h2><p>${esc(currentUser.name)} · ${fmt(reportPeriod)}${reportKind==='weekly'?' – '+fmt(end):''}</p></div></div>${submitted?empty('Bạn đã gửi báo cáo kỳ này','Bản chụp và nội dung đã chốt được giữ nguyên để quản lý đối chiếu.'):reportPeriod>today()?empty('Kỳ báo cáo chưa bắt đầu','Bạn có thể xem kế hoạch; báo cáo được gửi khi kỳ bắt đầu.'):`<form class="report-form" id="report-form">${field('Kết quả thực hiện & nguyên nhân *','<textarea name="result" required maxlength="12000" placeholder="Đã hoàn thành khâu nào? Sản phẩm và minh chứng ở đâu? Điều gì chưa đạt kế hoạch?"></textarea>',true)}${field('Vướng mắc & hỗ trợ cần thiết','<textarea name="blocker" maxlength="8000" placeholder="Đang chờ ai, cần quyết định gì, thời điểm cần hỗ trợ…"></textarea>',true)}${field(reportKind==='daily'?'Ưu tiên ngày tiếp theo *':'Kế hoạch tuần tiếp theo *','<textarea name="nextPlan" required maxlength="12000" placeholder="Công việc cụ thể, người phối hợp và mốc hoàn thành…"></textarea>',true)}<p style="font-size:11px;margin-top:16px">Khi gửi, hệ thống lưu bản chụp công việc của bạn trong kỳ. Nhận định có thể bao gồm cả việc thực hiện ngoài kỳ; không tự đổi trạng thái task.</p><div class="form-actions"><button class="primary">Gửi & chốt báo cáo</button></div></form>`}</section><section class="panel"><div class="panel-head"><div><h2>Báo cáo đã gửi · ${reports.length}</h2><p>${manager()?'Theo dõi và phản hồi báo cáo của từng thành viên.':'Lưu lại kết quả và phản hồi từ quản lý.'}</p></div></div>${reports.length?reports.map(reportCard).join(''):empty('Chưa có báo cáo','Báo cáo trong kỳ được chọn sẽ xuất hiện ở đây.')}</section></div><section class="panel"><div class="panel-head"><div><h2>Nội dung đến hạn trong kỳ</h2><p>${esc(user(selectedOwner).name)} · Có thể gồm phần việc phối hợp</p></div></div><div id="summary-tasks">${reportSummary?table(reportSummary.tasks):''}</div></section>`;
 $('#report-kind').onchange=e=>{reportKind=e.target.value;reportPeriod=today();reportSummary=null;render()};$('#report-period').onchange=e=>{if(e.target.value){reportPeriod=e.target.value;reportSummary=null;render()}};
 if(manager())$('#report-owner').onchange=e=>{reportOwner=e.target.value;reportSummary=null;render()};
 const form=$('#report-form');if(form)form.onsubmit=e=>{e.preventDefault();runForm(form,async()=>{const f=Object.fromEntries(new FormData(form));await api('/reports','POST',{kind:reportKind,period:reportPeriod,...f});reportSummary=null;await refresh();toast('Đã gửi báo cáo và lưu bản chụp dữ liệu của bạn.')})};
 $('#export-reports').onclick=()=>download(`bao-cao-${reportKind}-${reportPeriod}.json`,{kind:reportKind,period:reportPeriod,reports});
 document.querySelectorAll('[data-review-report]').forEach(b=>b.onclick=()=>reviewReportModal(Number(b.dataset.reviewReport)));
 document.querySelectorAll('[data-snapshot]').forEach(b=>b.onclick=()=>snapshotModal(Number(b.dataset.snapshot)));
 const requestKey=reportKind+reportPeriod+selectedOwner;
 api('/report-summary?'+new URLSearchParams({kind:reportKind,period:reportPeriod,ownerId:selectedOwner})).then(s=>{if(route!=='reports'||requestKey!==reportKind+reportPeriod+(reportOwner?Number(reportOwner):currentUser.id))return;reportSummary=s;$('#report-summary').innerHTML=summaryCards(s);$('#summary-tasks').innerHTML=table(s.tasks);bindCommon()}).catch(e=>{if($('#report-summary'))$('#report-summary').innerHTML=`<div class="form-error">${esc(e.message)}</div>`});
}
function summaryCards(s){return `<div class="stats">${[['Nội dung đến hạn',s.total,'tasks',''],['Đã nghiệm thu',s.done,'check',''],['Đang quá hạn',s.overdue,'clock','red'],['Đang có vướng mắc',s.blocked,'flag','gold']].map(([label,n,i,c])=>`<div class="stat ${c}"><span class="stat-top">${label}${icon(i)}</span><strong>${n}</strong><small>${esc(user(s.ownerId).name)}</small></div>`).join('')}</div>`}
function reportCard(r){return `<article class="report-card"><div class="report-meta"><strong>${esc(user(r.ownerId).name)}</strong>${badge(r.reviewStatus,{submitted:'Đã gửi',reviewed:'Đã kiểm tra'})}</div><p>${fmtTime(r.createdAt)} · ${r.kind==='daily'?'Báo cáo ngày':'Báo cáo tuần'}</p><div class="snapshot"><span>${r.snapshot.total} nội dung</span><span>${r.snapshot.done} nghiệm thu</span><span>${r.snapshot.overdue} quá hạn</span></div><h4>Kết quả & nhận định</h4><p>${esc(r.result)}</p><h4>Vướng mắc</h4><p>${esc(r.blocker||'Không ghi nhận')}</p><h4>Bước tiếp theo</h4><p>${esc(r.nextPlan)}</p>${r.reviewNote?`<div class="info-note" style="margin:16px 0 0"><strong>Phản hồi từ ${esc(user(r.reviewedBy).name)}</strong><br>${esc(r.reviewNote)}</div>`:''}<div class="actions" style="margin-top:16px"><button class="text-btn" data-snapshot="${r.id}">Xem bản chụp công việc ↗</button>${manager()&&r.ownerId!==currentUser.id?`<button class="text-btn" data-review-report="${r.id}">Nhận xét báo cáo</button>`:''}</div></article>`}
function reviewReportModal(id){const r=data.reports.find(r=>r.id===id);openModal(modalHead('Nhận xét báo cáo')+`<p class="modal-subtitle">${esc(user(r.ownerId).name)} · ${fmt(r.period)}${r.kind==='weekly'?' – '+fmt(r.end):''}</p><form id="review-report-form">${field('Nhận xét & hỗ trợ từ quản lý *',`<textarea name="reviewNote" required maxlength="8000" placeholder="Phản hồi cụ thể và hướng xử lý…">${esc(r.reviewNote)}</textarea>`)}<div class="form-actions"><button type="button" data-close>Hủy</button><button class="primary">Xác nhận đã kiểm tra</button></div></form>`,true);$('#review-report-form').onsubmit=e=>{e.preventDefault();runForm(e.target,async()=>{await api('/reports/'+r.id,'PATCH',{reviewStatus:'reviewed',reviewNote:new FormData(e.target).get('reviewNote')});closeModal();await refresh();toast('Đã lưu nhận xét báo cáo.')})}}
function snapshotModal(id){const r=data.reports.find(r=>r.id===id);openModal(modalHead('Bản chụp khi gửi báo cáo')+`<p class="modal-subtitle">${esc(user(r.ownerId).name)} · Ghi nhận ${fmtTime(r.createdAt)}. Các số liệu bên dưới được giữ tại thời điểm gửi.</p>${r.snapshot.tasks.length?r.snapshot.tasks.map(t=>`<div class="stage"><strong>${esc(t.title)}</strong><div class="pill-row">${badge(t.status)}<span class="status">Hạn ${fmt(t.due)}</span></div><p class="brief">Bước tiếp theo: ${esc(t.nextStep||'Chưa ghi nhận')}</p>${t.stages.map(s=>`<div class="history">${stageNames[s.key]} · ${esc(user(s.ownerId).name)} · ${stageStatus[s.status]}<br>${esc(s.note)}</div>`).join('')}${safeLink(t.evidence,'Sản phẩm bàn giao')}</div>`).join(''):empty('Không có nội dung đến hạn trong kỳ','Nhận định cá nhân vẫn được giữ trong báo cáo.')}`)}
function download(name,value){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
init();
